svg.desc:
// clk goes to every instance and is not drawn. rst_n_sync (output of the 2FF synchronizer) // is the reset of all six instances and is not drawn as a wire into them (convention). // View: control flow of gemm_accel_top. The data ports of u_dma, u_sram, u_array and u_vpu // (m_axi_*, scratchpad ports, a/b vectors, row stream, bias/C ports) are drawn in // gemm_accel_top_dataflow.svg and are omitted here; the port maps below are complete. // Abstraction: each interface -> one bundle wire labelled with the port-name group at each // end. FSM -> u_dma: o_rd_*/o_wr_* = {start, dst|fmt, base, rows, rwords, stride, bank, // abort}; u_dma -> FSM: o_rd_*/o_wr_* = {busy, done, error}, o_desc_* = {valid, idx, data}. // o_err_* = {err_pulse, err_code, err_desc_addr}; o_perf_* = {perf_load, perf_comp, // perf_store}; o_comp_bank_* = {a, b, bias, c}. // soft_clr is one net: u_main_fsm.o_soft_clr -> i_soft_clr of u_regfile, u_dma, u_sram, // u_array, u_vpu (synchronous one-cycle clear; never drives a flip-flop reset pin).
[reg_rst_sync0] rst_sync0_q <= 1'b1 @(rst=1'b0); // async assert, sync release
[reg_rst_sync1] rst_sync1_q <= rst_sync0_q @(rst=1'b0); rst_n_sync = rst_sync1_q; // reset of all six instances
[u_regfile] gemm_register_file u_regfile ( .s_axi_*(s_axi_*), .i_soft_clr(soft_clr), .o_start_pulse(start_pulse), .o_soft_req(soft_req), .o_cfg_desc_ptr(cfg_desc_ptr), .i_done_pulse(done_pulse), .i_err_pulse(err_pulse), .i_err_code(err_code), .i_perf_load(perf_load), .i_perf_comp(perf_comp), .i_perf_store(perf_store), .i_soft_busy(soft_busy), .i_err_desc_addr(err_desc_addr), .i_desc_done_cnt(desc_done_cnt));
[u_main_fsm] gemm_main_fsm u_main_fsm ( .i_start_pulse(start_pulse), .i_soft_req(soft_req), .i_cfg_desc_ptr(cfg_desc_ptr), .o_done_pulse(done_pulse), .o_err_pulse(err_pulse), .o_err_code(err_code), .o_perf_load(perf_load), .o_perf_comp(perf_comp), .o_perf_store(perf_store), .o_soft_busy(soft_busy), .o_err_desc_addr(err_desc_addr), .o_desc_done_cnt(desc_done_cnt), .o_soft_clr(soft_clr), .o_rd_start(rd_start), .o_rd_dst(rd_dst), .o_rd_base(rd_base), .o_rd_rows(rd_rows), .o_rd_rwords(rd_rwords), .o_rd_stride(rd_stride), .o_rd_bank(rd_bank), .o_rd_abort(rd_abort), .i_rd_busy(rd_busy), .i_rd_done(rd_done), .i_rd_error(rd_error), .i_desc_valid(desc_valid), .i_desc_idx(desc_idx), .i_desc_data(desc_data), .o_wr_start(wr_start), .o_wr_fmt(wr_fmt), .o_wr_base(wr_base), .o_wr_rows(wr_rows), .o_wr_rwords(wr_rwords), .o_wr_stride(wr_stride), .o_wr_bank(wr_bank), .o_wr_abort(wr_abort), .i_wr_busy(wr_busy), .i_wr_done(wr_done), .i_wr_error(wr_error), .o_pe_start(pe_start), .o_comp_dim(comp_dim), .i_pe_done(pe_done), .i_pe_busy(pe_busy), .o_comp_post_en(comp_post_en), .o_comp_relu_en(comp_relu_en), .o_comp_qm0(comp_qm0), .o_comp_qshift(comp_qshift), .o_comp_bank_a(comp_bank_a), .o_comp_bank_b(comp_bank_b), .o_comp_bank_bias(comp_bank_bias), .o_comp_bank_c(comp_bank_c), .o_comp_active(comp_active)); // no i_soft_clr: the FSM resets its own state in state T_CLR, the cycle it drives o_soft_clr
[u_dma] gemm_dma_engine u_dma ( .i_soft_clr(soft_clr), .i_rd_start(rd_start), .i_rd_dst(rd_dst), .i_rd_base(rd_base), .i_rd_rows(rd_rows), .i_rd_rwords(rd_rwords), .i_rd_stride(rd_stride), .i_rd_bank(rd_bank), .i_rd_abort(rd_abort), .o_rd_busy(rd_busy), .o_rd_done(rd_done), .o_rd_error(rd_error), .o_desc_valid(desc_valid), .o_desc_idx(desc_idx), .o_desc_data(desc_data), .i_wr_start(wr_start), .i_wr_fmt(wr_fmt), .i_wr_base(wr_base), .i_wr_rows(wr_rows), .i_wr_rwords(wr_rwords), .i_wr_stride(wr_stride), .i_wr_bank(wr_bank), .i_wr_abort(wr_abort), .o_wr_busy(wr_busy), .o_wr_done(wr_done), .o_wr_error(wr_error), .o_spm_wr_valid(dw_valid), .o_spm_wr_buf(dw_buf), .o_spm_wr_bank(dw_bank), .o_spm_wr_addr(dw_addr), .o_spm_wr_data(dw_data), .i_spm_wr_ready(dw_ready), .o_spm_rd_valid(dr_valid), .o_spm_rd_bank(dr_bank), .o_spm_rd_addr(dr_addr), .i_spm_rd_ready(dr_ready), .i_spm_rd_rvalid(dr_rvalid), .i_spm_rd_rdata(dr_rdata), .m_axi_*(m_axi_*));
[u_sram] gemm_local_sram u_sram ( .i_soft_clr(soft_clr), .i_dw_valid(dw_valid), .i_dw_buf(dw_buf), .i_dw_bank(dw_bank), .i_dw_addr(dw_addr), .i_dw_data(dw_data), .o_dw_ready(dw_ready), .i_dr_valid(dr_valid), .i_dr_bank(dr_bank), .i_dr_addr(dr_addr), .o_dr_ready(dr_ready), .o_dr_rvalid(dr_rvalid), .o_dr_rdata(dr_rdata), .i_comp_bank_a(comp_bank_a), .i_comp_bank_b(comp_bank_b), .i_comp_bank_bias(comp_bank_bias), .i_comp_bank_c(comp_bank_c), .i_comp_active(comp_active), .i_a_rd_en(a_rd_en), .i_a_rd_row(a_rd_row), .i_a_rd_k(a_rd_k), .o_a_rd_data(a_rd_data), .i_b_rd_en(b_rd_en), .i_b_rd_k(b_rd_k), .i_b_rd_col(b_rd_col), .o_b_rd_data(b_rd_data), .i_bias_rd_en(bias_rd_en), .i_bias_rd_col(bias_rd_col), .o_bias_rd_data(bias_rd_data), .i_c_wr_en(c_wr_en), .i_c_wr_fmt(c_wr_fmt), .i_c_wr_row(c_wr_row), .i_c_wr_col(c_wr_col), .i_c_wr_data(c_wr_data), .i_c_wr_mask(c_wr_mask)); // 4 buffers x NB=2 banks: A 256, B 256, C 1024, BIAS 32 words per bank (3136 words, 12.25 KiB) // read latency is exactly 1 cycle; o_dw_ready = o_dr_ready = 1'b1 (no backpressure)
[u_array] gemm_systolic_array u_array ( // P = 8, 64 PE, output-stationary .i_soft_clr(soft_clr), .i_pe_start(pe_start), .i_matrix_dim(comp_dim), .o_pe_done(pe_done), .o_busy(pe_busy), .o_a_rd_en(a_rd_en), .o_a_rd_row(a_rd_row), .o_a_rd_k(a_rd_k), .i_a_rd_data(a_rd_data), .o_b_rd_en(b_rd_en), .o_b_rd_k(b_rd_k), .o_b_rd_col(b_rd_col), .i_b_rd_data(b_rd_data), .o_row_valid(row_valid), .o_row_idx(row_idx), .o_row_col(row_col), .o_row_data(row_data), .o_row_mask(row_mask)); // o_a_rd_en == o_b_rd_en always; o_pe_done = o_final delayed L_VPU + 1 = 5 cycles
[u_vpu] gemm_vpu u_vpu ( // 8 lanes, LAT = 3 + MUL_STAGES = 4 .i_soft_clr(soft_clr), .i_post_en(comp_post_en), .i_relu_en(comp_relu_en), .i_quant_m0(comp_qm0), .i_quant_shift(comp_qshift), .i_row_valid(row_valid), .i_row_idx(row_idx), .i_row_col(row_col), .i_row_data(row_data), .i_row_mask(row_mask), .o_bias_rd_en(bias_rd_en), .o_bias_rd_col(bias_rd_col), .i_bias_rd_data(bias_rd_data), .o_c_wr_en(c_wr_en), .o_c_wr_fmt(c_wr_fmt), .o_c_wr_row(c_wr_row), .o_c_wr_col(c_wr_col), .o_c_wr_data(c_wr_data), .o_c_wr_mask(c_wr_mask)); // o_bias_rd_en = i_row_valid & i_post_en and o_bias_rd_col = i_row_col are the only // combinational input-to-output path of the VPU (the DMA has two more: m_axi_rready and // o_spm_wr_valid/o_spm_wr_data, see the system spec integration rules)
